const html = $json.data || $json.body || '';

// ─────────────────────────────────────────────────────────────
// Bot-challenge / interstitial detection
// ─────────────────────────────────────────────────────────────

// High-confidence markers in RAW html (these live inside <script>/<meta>,
// so this MUST run before script stripping)
const CHALLENGE_HTML_MARKERS = [
  '/cdn-cgi/challenge-platform',
  'cf-browser-verification',
  '__cf_chl',
  'cf_chl_opt',
  '_incapsula_resource',
  'distil_r_captcha',
  'px-captcha',
  '/captcha/',
  'g-recaptcha',
  'hcaptcha.com',
  'datadome',
  'perimeterx',
  'akamai bot manager',
];

// Phrases that appear in the visible text of challenge / block pages
const CHALLENGE_TEXT_PHRASES = [
  'client challenge',
  'javascript is disabled in your browser',
  'enable javascript and cookies to continue',
  'please enable javascript',
  'please turn on javascript',
  'javascript is required',
  'requires javascript to be enabled',
  'checking your browser before accessing',
  'verify you are human',
  'verifying you are human',
  'are you a robot',
  'i am not a robot',
  'complete the security check',
  'security check to access',
  'attention required cloudflare',
  'ddos protection by cloudflare',
  'access to this page has been denied',
  'access denied you don t have permission',
  'your request has been blocked',
  'unusual traffic from your computer network',
  'this site requires cookies',
  'ray id',
  '403 forbidden',
  'just a moment',
];

// Normalise text the same way for both raw + final checks
function normalise(text) {
  return (text || '')
    .toLowerCase()
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function findChallengePhrase(normalisedText) {
  return CHALLENGE_TEXT_PHRASES.find(p => normalisedText.includes(p)) || null;
}

// Stage 1 — raw HTML markers (run FIRST, before scripts are stripped)
const rawLower = html.toLowerCase();
const htmlMarker = CHALLENGE_HTML_MARKERS.find(m => rawLower.includes(m));
if (htmlMarker) {
  throw new Error(`Bot challenge page detected (marker: ${htmlMarker}) — skipping`);
}

// <title>Just a moment...</title> / <title>Client Challenge</title>
const titleMatch = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
if (titleMatch) {
  const t = normalise(titleMatch[1]);
  const titleHit = findChallengePhrase(t);
  if (titleHit) {
    throw new Error(`Bot challenge page detected (title: "${titleHit}") — skipping`);
  }
}

// ─────────────────────────────────────────────────────────────
// Tag-spam detection (unchanged)
// ─────────────────────────────────────────────────────────────
function isTagSpam(text) {
  const t = (text || '').trim();
  return /([A-Z0-9_]+;){5,}/.test(t);
}

// 1. Remove unwanted sections
let cleaned = html
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<noscript[\s\S]*?<\/noscript>/gi, '')
  .replace(/<nav[\s\S]*?<\/nav>/gi, '')
  .replace(/<footer[\s\S]*?<\/footer>/gi, '')
  .replace(/<header[\s\S]*?<\/header>/gi, '')
  .replace(/<aside[\s\S]*?<\/aside>/gi, '');

function extractText(h) {
  return h
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s{2,}/g, ' ')
    .trim();
}

// 2. Prefer article/main
const articleMatch = cleaned.match(/<article[\s\S]*?<\/article>/i);
const mainMatch = cleaned.match(/<main[\s\S]*?<\/main>/i);

let articleText = extractText(articleMatch?.[0] || '');
let mainText = extractText(mainMatch?.[0] || '');

if (isTagSpam(articleText)) articleText = '';
if (isTagSpam(mainText)) mainText = '';

let content;

if (articleText.length > 500) {
  content = articleText;
} else if (mainText.length > 500) {
  content = mainText;
} else {
  const fullText = extractText(cleaned);
  if (isTagSpam(fullText)) {
    throw new Error('Tag-spam content detected — skipping');
  }
  content = fullText;
}

// Stage 2 — visible-text challenge check (before punctuation is destroyed)
const normalisedContent = normalise(content);
const textHit = findChallengePhrase(normalisedContent);
if (textHit) {
  // Challenge pages are short. A real article that merely *mentions* one of
  // these phrases will be long, so only reject when the page is also thin.
  if (normalisedContent.length < 1500) {
    throw new Error(`Bot challenge page detected (text: "${textHit}") — skipping`);
  }
}

// 3. Decode HTML entities
content = content
  .replace(/&#39;/g, "'")
  .replace(/&quot;/g, '"')
  .replace(/&nbsp;/g, ' ')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&bull;/g, '•')
  .replace(/&[a-z]+;/gi, ' ');

// 4. Remove CSS/Tailwind garbage
content = content.replace(/\[[^\]]*\]:[^\s]+/g, '');
content = content.replace(/:[a-zA-Z-]+\b/g, '');

// 5. Keep only letters, numbers, spaces, currency symbols
content = content.replace(/[^a-zA-Z0-9\s£$€¥¢₺₹₩₪₫₭₮₯₱₲₳₴₵₶₷₸₹₺₻₼₽₾₿&]/g, ' ');

// 6. Clean whitespace
content = content.replace(/\s{2,}/g, ' ').trim();

// 7. Slice for DB safety
content = content.slice(0, 10000);

// 8. Reject if too short
if (content.length < 150) {
  throw new Error(`Content too short (${content.length} chars) — skipping`);
}

return { json: { text: content } };
